// 1. Header (Widget.h): Hides details, decouples compilation
struct WidgetImpl; // Forward declaration

class Widget {
private:
    // Requires declaration, not definition, of WidgetImpl
    std::unique_ptr<WidgetImpl> pImpl; 

public:
    Widget();
    // Dtor MUST be declared out-of-line 
    // when using unique_ptr/Pimpl (requires complete type)
    ~Widget(); 
    void operation();
};

// 2. Source (Widget.cpp): Defines details, provides implementation
// Note: Includes required headers (e.g., <vector>) only here

struct WidgetImpl {
    std::vector<int> internal_data;
    void helper() { /* ... */ }
};

Widget::Widget() 
    : pImpl(std::make_unique<WidgetImpl>()) 
{}

// Dtor needs the full definition of WidgetImpl to execute unique_ptr::reset()
Widget::~Widget() = default;

void Widget::operation() {
    pImpl->helper();
}
